<script setup>
import { Box, Brush, Eraser, MousePointer2, PencilLine, Pipette, Shapes, Type } from 'lucide-vue-next'
defineProps({ tools:{type:Array,required:true}, activeTool:{type:String,required:true}, selectedKind:{type:String,default:null}, selectionOpen:{type:Boolean,default:false}, shortcuts:{type:Object,required:true}, labels:{type:Object,required:true} })
defineEmits(['choose','toggle-selection'])
</script>
<template><nav class="tool-dock" aria-label="Map tools"><button v-for="tool in tools" :key="tool.id" :class="['dock-tool',{active:activeTool===tool.id}]" :title="`${tool.label} (${shortcuts[tool.id]})`" :aria-label="tool.label" @click="$emit('choose',tool)"><kbd class="dock-shortcut" aria-hidden="true">{{shortcuts[tool.id]}}</kbd><MousePointer2 v-if="tool.id==='select'" aria-hidden="true"/><Brush v-else-if="tool.id==='terrain'" aria-hidden="true"/><Pipette v-else-if="tool.id==='eyedropper'" aria-hidden="true"/><Shapes v-else-if="tool.id==='room'" aria-hidden="true"/><PencilLine v-else-if="tool.id==='wall'" aria-hidden="true"/><Box v-else-if="tool.id==='object'" aria-hidden="true"/><Type v-else-if="tool.id==='label'" aria-hidden="true"/><Eraser v-else aria-hidden="true"/><small aria-hidden="true">{{labels[tool.id]}}</small></button><button v-if="selectedKind==='label'" class="dock-tool" :class="{active:selectionOpen}" title="Selection" @click="$emit('toggle-selection')"><MousePointer2 aria-hidden="true"/><small>Selection</small></button></nav></template>
